/* Preguntas elaboradas exclusivamente a partir de los seis archivos adjuntos. */
const FUENTES = {
 c4: 'T6 - Jiménez, Guillermo (2012) Guía ICC del Comercio Internacional Prácticas globales para exportar e importar - Capítulo 4.pdf',
 c5: 'T6 - Jiménez, Guillermo (2012) Guía ICC del Comercio Internacional Prácticas globales para exportar e importar - Capítulo 5.pdf',
 c6: 'T6 - Jiménez, Guillermo (2012) Guía ICC del Comercio Internacional Prácticas globales para exportar e importar - Capítulo 6.pdf',
 p17: 'Clase 17 - 13-10-26.pptx', p18: 'Clase 18 - 15-10-26.pptx',
 n: 'CL3  Notas y resumenes mio- Contratos de Compraventa internacional.pdf'
};
const R = (file,loc) => ({file,loc});
const M = (text,right,wrong,explanation) => ({type:'mc',text,options:[right,...wrong],answer:0,explanation});
const T = (text,answer,explanation) => ({type:'tf',text,options:['Verdadero','Falso'],answer:answer?0:1,explanation});
const C = (id,chapter,title,weight,refs,items) => ({id,chapter,title,weight,refs,items});
const CONCEPTOS = [
C('acuerdo',4,'Formación y elementos del contrato',3,[R('p17','diapositivas 3–4 y 10–11'),R('n','páginas PDF 1–2')],[
 M('¿Qué característica distingue un contrato de compraventa de un simple intercambio de información?','Genera obligaciones jurídicamente exigibles entre las partes.',['Requiere reunir todas sus condiciones en un documento firmado.','Se limita a comunicar un precio sin intención de obligarse.','Exige una solicitud y una contraoferta en todos los casos.'],'El compromiso vinculante diferencia el contrato de la negociación. La solicitud y la contraoferta son pasos posibles, no requisitos universales.'),
 M('Las partes identifican los bienes, fijan cantidad y precio y expresan válidamente su acuerdo. ¿Qué detalle puede completarse mediante reglas supletorias de la CISG, si esta resulta aplicable?','El lugar de entrega.',['La identidad del bien que se negocia.','La existencia de una aceptación válida.','La intención de quedar obligado.'],'La clase menciona reglas supletorias de lugar y fecha de entrega. No todos los detalles de ejecución son indispensables para formar el acuerdo.'),
 T('La solicitud inicial y la contraoferta pueden faltar sin impedir que una oferta y una aceptación válidas formen el contrato.',true,'Es correcto: la solicitud y la contraoferta no son necesarias; el contrato se concreta cuando la aceptación surte efecto.'),
 T('Para formar el contrato, la cantidad y el precio deben estar expresados en cifras fijas; no basta prever criterios para determinarlos.',false,'El error es exigir cifras fijas. Corrección: la cantidad y el precio pueden estar definidos o ser determinables mediante criterios suficientes.')
]),
C('oferta',4,'Oferta y aceptación',3,[R('c4','páginas PDF 7 y 11 (impresas 71 y 75), §§4.5–4.7'),R('p17','diapositiva 4')],[
 M('¿Cuál reúne los rasgos de una oferta contractual?','Una propuesta suficientemente precisa con intención de obligarse si es aceptada.',['Una consulta sobre la disponibilidad de un producto.','Una lista publicitaria de precios sin intención de quedar obligado.','Una petición de información sobre condiciones de entrega.'],'No basta mencionar un precio. Se necesita precisión suficiente e intención de vincularse mediante la aceptación.'),
 M('Según la regla de formación explicada en la lectura, ¿cuándo surte efecto la aceptación?','Cuando llega al oferente.',['Cuando el destinatario envía su aceptación, aunque no haya llegado al oferente.','Cuando se emite la solicitud que precedió a la oferta.','Cuando se formula una contraoferta aún no aceptada.'],'La lectura distingue enviar una aceptación de que esta llegue al oferente, que es el momento de eficacia indicado.'),
 T('Indicar un precio durante una negociación no basta, por sí solo, para demostrar una oferta vinculante.',true,'Es correcto: también debe existir intención de obligarse y una propuesta suficientemente precisa.'),
 T('Una solicitud de cotización obliga al vendedor a celebrar la venta en cuanto el comprador la envía.',false,'Se confunde solicitud con oferta. Corrección: la solicitud pide información u oferta; el acuerdo exige una oferta y una aceptación válidas.')
]),
C('contraoferta',4,'Contraoferta y conflicto de formularios',3,[R('c4','páginas PDF 7 y 12 (impresas 71 y 76), §§4.5 y 4.7'),R('p17','diapositivas 4–5')],[
 M('Se ofrecen herramientas para entrega en abril. El comprador responde: «Acepto, pero la entrega debe ser en junio». El plazo es sustancial. ¿Qué es esta respuesta?','Una contraoferta que requiere aceptación.',['Una aceptación incondicional de la oferta original.','Una solicitud inicial sin efecto sobre la oferta.','Un contrato resuelto por incumplimiento.'],'Cambiar sustancialmente la fecha de entrega altera la oferta. Aceptar precio y cantidad no elimina ese cambio.'),
 M('En el intercambio de formularios, la respuesta solo añade un detalle no sustancial. Según el tratamiento descrito en la lectura, ¿qué puede ocurrir?','Puede formar el contrato si el oferente no se opone sin demora.',['Toda diferencia obliga a iniciar otra negociación desde cero.','Las condiciones del comprador prevalecen por ser comprador.','La diferencia resuelve un contrato previamente incumplido.'],'La lectura distingue cambios sustanciales de cambios menores. No toda diferencia documental recibe el mismo tratamiento.'),
 T('El conflicto de formularios puede aparecer cuando la proforma y la orden de compra incorporan condiciones generales distintas.',true,'Es correcto: las condiciones pueden contradecirse, por ejemplo, sobre arbitraje o tribunales. Deben aclararse las discrepancias.'),
 T('Cambiar sustancialmente la cantidad equivale a aceptar la oferta siempre que el precio unitario no cambie.',false,'El error es ignorar el cambio de cantidad. Corrección: una modificación sustancial puede ser rechazo y contraoferta, aunque conserve el precio unitario.')
]),
C('forma',4,'Contratos verbales y documentación',3,[R('c4','páginas PDF 3–4 (impresas 67–68), §4.2'),R('p17','diapositivas 6–9')],[
 M('¿Cuál NO es una ventaja práctica de la contratación no escrita señalada en clase?','Facilita demostrar con precisión todas las condiciones pactadas.',['Puede permitir cerrar operaciones con rapidez.','Reduce el costo de preparación documental.','Ofrece flexibilidad en intercambios sencillos.'],'La prueba de lo acordado es una limitación del acuerdo no escrito. Su agilidad no elimina malentendidos ni dificultades probatorias.'),
 M('¿Qué caracteriza al documento contractual integrado frente al intercambio de correos y formularios?','Reúne las condiciones y responsabilidades en un texto único.',['Impide que exista cualquier controversia posterior.','Es la única forma en que nace un contrato exigible.','Elimina el tiempo de redacción y revisión.'],'El texto integrado facilita identificar y probar lo pactado, pero exige preparación. Los documentos intercambiados también pueden formar un contrato.'),
 T('Un acuerdo verbal puede ser exigible bajo el marco correspondiente, aunque sea más difícil probar su contenido.',true,'Es correcto: la exigibilidad y la facilidad de prueba son asuntos diferentes. Deben considerarse las exigencias de forma aplicables.'),
 T('Un conjunto de correos y documentos comerciales no puede constituir un contrato porque carece de un documento único llamado «contrato».',false,'El error es confundir el acuerdo con su soporte. Corrección: comunicaciones y documentos pueden formar conjuntamente un contrato vinculante.')
]),
C('cisg',4,'Ámbito de la CISG',3,[R('c4','páginas PDF 6–8 (impresas 70–72), §4.5'),R('p17','diapositiva 15')],[
 M('¿Qué materia queda fuera del ámbito de la CISG, según la lectura?','Los efectos de la compraventa sobre la transmisión de propiedad.',['La formación del contrato dentro de su ámbito.','Las obligaciones de comprador y vendedor.','Los remedios frente al incumplimiento de la compraventa.'],'La lectura remite los efectos sobre la propiedad al derecho nacional. No debe confundirse esta exclusión con las obligaciones de la venta.'),
 M('¿Cuál describe correctamente la CISG en el material?','Es una convención internacional que proporciona reglas uniformes para determinadas compraventas de mercancías.',['Es un contrato privado que ICC firma por las empresas.','Es una norma nacional peruana sobre trámites aduaneros.','Es un sistema que sustituye todos los derechos nacionales en cualquier operación.'],'Su finalidad es uniformar reglas en su ámbito; no abarca toda operación ni elimina el derecho nacional. Las notas que dicen «Tratado Nacional» contienen un error.'),
 T('La CISG regula la formación y las obligaciones de la compraventa en su ámbito, pero no todos los aspectos jurídicos de la operación.',true,'Es correcto: por ejemplo, los efectos sobre la propiedad quedan fuera. Se distingue la obligación de transferir del régimen de sus efectos.'),
 T('La CISG y los Incoterms determinan por sí solos el momento en que se transmite el título de propiedad.',false,'El error es atribuirles el régimen de propiedad. Corrección: debe examinarse el derecho nacional aplicable y lo válidamente pactado; ni la CISG ni los Incoterms cubren esos efectos.')
]),
C('exclusiones',4,'Exclusiones de la CISG',1,[R('c4','página PDF 7 (impresa 71), §4.5.a'),R('n','página PDF 8')],[
 M('¿Cuál de estas operaciones está expresamente excluida del ámbito descrito de la CISG?','La venta para uso personal.',['Una venta internacional de herramientas para reventa.','Una venta internacional de mobiliario entre empresas.','Una venta comercial internacional de tejidos.'],'La lectura incluye las ventas para uso personal entre las exclusiones. Las otras son ejemplos de bienes comerciados entre empresas.'),
 M('¿Cuál NO aparece entre las exclusiones de operaciones mencionadas en la lectura?','La compraventa internacional de ropa para reventa.',['La compraventa de electricidad.','La compraventa de aeronaves.','Las operaciones sobre valores.'],'La ropa para reventa es mercancía comercial. Electricidad, aeronaves y valores figuran expresamente entre las exclusiones descritas.'),
 T('En el ámbito presentado, un contrato en el que los servicios desempeñan un papel preponderante no queda sometido automáticamente a la CISG.',true,'Es correcto: la lectura excluye la aplicación automática cuando predominan los servicios. No equivale a una compraventa ordinaria de bienes.'),
 T('La CISG se aplica automáticamente a cualquier contrato internacional, incluidas las operaciones de valores.',false,'El error es ampliar su ámbito a toda operación. Corrección: la CISG tiene restricciones y excluye, entre otras, las operaciones sobre valores.')
]),
C('autonomia',4,'Autonomía y exclusión de la CISG',2,[R('c4','páginas PDF 6–7 (impresas 70–71), §4.5'),R('c5','página PDF 4 (impresa 81), §5.1')],[
 M('Las partes eligen la ley de un país que integra la CISG en su derecho. ¿Qué conclusión es correcta?','La elección de esa ley no excluye necesariamente la CISG.',['La CISG queda excluida por mencionar cualquier país.','Ya no hace falta distinguir ley aplicable de foro.','La elección convierte a ICC en tribunal competente.'],'La CISG puede formar parte del derecho elegido. La lectura exige atención a su exclusión expresa, no asumirla por elegir una ley nacional.'),
 M('¿Qué expresa el principio de autonomía de las partes en el material?','Pueden excluir la CISG o modificar el efecto de sus disposiciones dentro de los límites correspondientes.',['Pueden ignorar toda norma nacional obligatoria.','Deben aplicar íntegramente la CISG sin modificar nada.','Pueden imponer unilateralmente condiciones nuevas tras la aceptación.'],'La libertad contractual permite excluir o variar disposiciones, pero no autoriza a desconocer sin límites otras normas ni a modificar unilateralmente lo pactado.'),
 T('Las partes pueden usar la CISG como marco principal y recurrir a una ley nacional para asuntos no cubiertos.',true,'Es correcto: la lectura contempla emplear el derecho nacional para cubrir vacíos y cuestiones fuera del ámbito de la Convención.'),
 T('Elegir una ley nacional y excluir expresamente la CISG son siempre decisiones equivalentes.',false,'El error es tratarlas como equivalentes. Corrección: una ley nacional puede incluir la CISG; excluirla puede requerir una disposición expresa.')
]),
C('sistemas',4,'Familias jurídicas',1,[R('c4','páginas PDF 4–5 (impresas 68–69), §4.3')],[
 M('¿Qué familia jurídica se caracteriza en la lectura por el papel central de los precedentes judiciales?','Common law o derecho consuetudinario.',['Derecho civil o continental.','Sharía o derecho islámico.','Lex mercatoria como código estatal único.'],'En el common law los fallos anteriores tienen un papel central. El derecho civil destaca por sus códigos y la sharía por sus fuentes religiosas.'),
 M('¿Cuál es la asociación correcta?','Derecho civil o continental: importancia de leyes y códigos.',['Common law: ausencia de leyes escritas.','Sharía: exclusión de toda fuente religiosa.','Derecho civil: identidad absoluta entre las normas de todos sus países.'],'La clasificación describe rasgos predominantes. El common law también tiene leyes y los países de una familia no tienen normas idénticas.'),
 T('La sharía atribuye importancia a principios religiosos como fuente jurídica, según la clasificación del capítulo.',true,'Es correcto: este es el rasgo que la lectura contrasta con las familias civil y consuetudinaria.'),
 T('Dos países de common law tienen necesariamente reglas comerciales idénticas.',false,'El error es confundir familia con identidad normativa. Corrección: incluso sistemas de una misma familia pueden presentar diferencias importantes.')
]),
C('conformidad',4,'Conformidad de la mercancía',3,[R('c4','página PDF 8 (impresa 72), §4.5.b'),R('p17','diapositiva 14')],[
 M('¿Qué debe examinarse para determinar si la mercancía es conforme, según la clase?','Cantidad, calidad, tipo y embalaje acordados.',['Solo que el vendedor haya enviado alguna mercancía.','Únicamente que la factura tenga el precio correcto.','Solo la fecha en que se contrata el seguro.'],'La conformidad atañe a las características pactadas de los bienes y su embalaje. No se satisface únicamente con enviar algo o emitir una factura.'),
 M('Se pactan herramientas de un tipo específico y el vendedor entrega otro tipo con el mismo valor. ¿Cuál es el problema?','Falta de conformidad respecto del tipo acordado.',['Cumplimiento conforme, porque el valor económico es el mismo.','Una modificación contractual aceptada necesariamente por el comprador.','Una falta exclusiva de documentación, sin relación con la mercancía.'],'Mantener el valor no corrige entregar un tipo distinto. El tipo forma parte de la conformidad exigida.'),
 T('La aptitud para el uso ordinario y, bajo las condiciones pertinentes, para un uso especial comunicado al vendedor puede ser relevante para la conformidad.',true,'Es correcto: la lectura añade estas exigencias a las características expresamente pactadas.'),
 T('Si la cantidad y el precio son correctos, un embalaje contrario a lo acordado no afecta la conformidad.',false,'El error es excluir el embalaje. Corrección: también debe corresponder a lo pactado, junto con cantidad, calidad y tipo.')
]),
C('aviso',4,'Inspección y aviso de defectos',3,[R('c4','página PDF 8 (impresa 72), §4.5.b'),R('n','página PDF 9')],[
 M('El comprador descubre un defecto y desea invocar la falta de conformidad. ¿Qué debe cuidar además de probar el defecto?','Comunicarlo dentro del plazo correspondiente.',['Esperar indefinidamente hasta que el vendedor lo descubra.','Dejar que la mercancía se deteriore para elevar el reclamo.','Prescindir de revisar el contenido del contrato.'],'La lectura advierte que la falta de comunicación oportuna puede hacer perder el derecho a invocar la no conformidad.'),
 M('¿Cuál es la afirmación INCORRECTA sobre los defectos?','La existencia del defecto permite al comprador ignorar los plazos de notificación.',['El comprador debe inspeccionar la mercancía.','El aviso oportuno de la falta de conformidad importa.','Pueden pactarse disposiciones sobre la notificación de defectos.'],'Tener un defecto real no vuelve irrelevantes los plazos. La revisión y la comunicación forman parte de la gestión del reclamo.'),
 T('El momento en que el comprador descubrió o debió descubrir el defecto es relevante para el plazo de comunicación descrito.',true,'Es correcto: la lectura se refiere a un plazo razonable desde el descubrimiento real o debido.'),
 T('Inspeccionar la mercancía sustituye la necesidad de comunicar la falta de conformidad al vendedor.',false,'Se confunden dos actuaciones. Corrección: revisar los bienes y avisar los defectos son pasos distintos; la inspección no sustituye la notificación.')
]),
C('esencial',4,'Incumplimiento esencial y ordinario',3,[R('c4','página PDF 9 (impresa 73), §4.6.a'),R('p18','diapositivas 9–10')],[
 M('¿Qué distingue al incumplimiento esencial?','Priva sustancialmente a la contraparte de lo que tenía derecho a esperar.',['Es cualquier diferencia, por pequeña que sea.','Solo puede cometerlo el vendedor.','Se identifica únicamente por el número de días de demora.'],'La gravedad depende del perjuicio concreto y del contrato, no de que exista cualquier desviación ni de quién incumpla.'),
 M('Se cumple lo principal y existe una merma comercialmente insignificante. ¿Qué concepto usa la lectura?','Cumplimiento sustancial.',['Incumplimiento esencial automático.','Exequátur.','Reserva de dominio ampliada.'],'La lectura contrapone el cumplimiento de lo principal con desviaciones menores al incumplimiento que destruye sustancialmente el beneficio esperado.'),
 T('La falta de recepción o de colaboración necesaria por el comprador puede constituir incumplimiento.',true,'Es correcto: las obligaciones del comprador no se agotan en pagar; también incluyen recibir y facilitar la entrega cuando corresponda.'),
 T('Toda entrega tardía autoriza a resolver de inmediato el contrato por incumplimiento esencial.',false,'El error es equiparar cualquier retraso a uno esencial. Corrección: deben examinarse sus efectos, lo pactado y los requisitos del remedio.')
]),
C('remedios',4,'Remedios y sus requisitos',3,[R('c4','páginas PDF 9–10 (impresas 73–74), §4.6'),R('p18','diapositivas 11–12')],[
 M('¿De qué dependen las soluciones jurídicas disponibles ante un incumplimiento?','Del contrato, el derecho aplicable y la naturaleza y gravedad del incumplimiento.',['Solo de que el comprador prefiera terminar la operación.','Solo de la nacionalidad del transportista.','Del nombre del documento usado, sin atender a su contenido.'],'La lectura identifica esos tres factores. Un remedio no se aplica automáticamente a cualquier incumplimiento.'),
 M('El vendedor corrige un defecto cuando procede. ¿Qué concepto corresponde?','Subsanación.',['Mitigación del daño por el comprador.','Resolución del contrato.','Renuncia al derecho de reclamar.'],'Subsanar es corregir el incumplimiento. Reconocer sentencias, elegir tribunal y retener la propiedad tienen funciones diferentes.'),
 T('La reducción del precio y la indemnización son remedios distintos que deben examinarse conforme a sus requisitos.',true,'Es correcto: el material enumera varios remedios; no convierte su disponibilidad en automática ni los trata como la misma medida.'),
 T('La resolución elimina necesariamente los derechos por daños y las cláusulas sobre controversias.',false,'El error es ampliar sus efectos a todo. Corrección: puede dar lugar a restituciones y no elimina necesariamente ni las cláusulas de controversias ni los derechos por daños.')
]),
C('mitigacion',4,'Mitigación del daño',3,[R('c4','páginas PDF 9–10 (impresas 73–74), §4.6'),R('p18','diapositiva 12')],[
 M('Un lote de tomates es de calidad inferior a la pactada, pero todavía puede venderse. ¿Qué conducta refleja la mitigación?','Adoptar medidas razonables para venderlo y reducir las pérdidas.',['Dejarlo pudrir para reclamar una suma mayor.','Suponer que la indemnización será ilimitada.','Eliminar los documentos que prueban el defecto.'],'La lectura utiliza este ejemplo para exigir esfuerzos razonables de reducción del daño, sin negar el incumplimiento inicial.'),
 M('Un comprador recibe bienes defectuosos que todavía tienen valor comercial. ¿Qué afirmación es INCORRECTA?','Puede agravarse deliberadamente el daño porque el vendedor incumplió primero.',['Deben considerarse medidas razonables para limitar las pérdidas.','El deber de reducir el daño no borra el incumplimiento original.','La posibilidad de aprovechar comercialmente los bienes puede ser relevante.'],'El incumplimiento del vendedor no autoriza a aumentar las pérdidas. Mitigar exige medidas razonables para reducirlas.'),
 T('La parte perjudicada debe adoptar medidas razonables para reducir sus pérdidas.',true,'Es correcto: mitigar es limitar el daño; no significa que el incumplimiento desaparezca ni que se pierda automáticamente todo reclamo.'),
 T('El deber de mitigar permite aumentar deliberadamente las pérdidas para fortalecer la reclamación.',false,'La afirmación invierte el deber. Corrección: deben tomarse medidas razonables para reducir las pérdidas, no agravarlas deliberadamente.')
]),
C('precontrato',4,'Negociación y cartas de intenciones',1,[R('c4','páginas PDF 11–12 (impresas 75–76), §4.7')],[
 M('¿Qué afirmación es correcta sobre una carta de intenciones?','Puede llegar a ser vinculante según su contenido y la ley aplicable.',['Su nombre garantiza que nunca obliga.','Siempre equivale a un laudo arbitral.','Sustituye por sí sola cualquier autorización pendiente.'],'Los efectos no dependen solo del título. El detalle, las reservas y el marco jurídico influyen en su posible fuerza vinculante.'),
 M('¿Cuál es un riesgo de las declaraciones realizadas durante las negociaciones?','Las afirmaciones engañosas pueden generar responsabilidad.',['Toda consulta inicial forma automáticamente el contrato definitivo.','La fase previa carece de cualquier relevancia jurídica.','Un catálogo obliga necesariamente a aceptar todos los pedidos.'],'La lectura admite libertad de negociación, pero advierte sobre declaraciones engañosas y recomienda buena fe.'),
 T('Un acuerdo preliminar puede servir mientras se espera la aprobación de un préstamo o una autorización.',true,'Es correcto: permite avanzar en aspectos básicos con asuntos pendientes; eso no resuelve por sí solo cuáles serán sus efectos vinculantes.'),
 T('Llamar «memorando» a un documento impide que un tribunal lo considere vinculante.',false,'El error es dar al nombre un efecto absoluto. Corrección: los efectos del acuerdo preliminar dependen de su contenido, circunstancias y ley aplicable.')
]),
C('instituciones',4,'Instituciones y marcos normativos',2,[R('p17','diapositivas 15–16')],[
 M('¿Qué institución se asocia en clase con requisitos y certificación sanitaria y fitosanitaria agropecuaria en Perú?','SENASA.',['PROMPERÚ.','CNUDMI/UNCITRAL.','ICC.'],'La clase asigna esa función a SENASA. PROMPERÚ apoya a exportadores; ICC elabora reglas comerciales y CNUDMI elaboró la CISG.'),
 M('¿Cuál es la asociación INCORRECTA?','ICC: autoridad pública que aprueba los contratos de cada exportador.',['SUNAT/Aduanas: despacho aduanero, tributos y formalidades.','PROMPERÚ: información y apoyo a empresas exportadoras.','MINCETUR: política y acuerdos comerciales.'],'ICC desarrolla reglas y modelos; no es una autoridad pública que apruebe contratos. CNUDMI tampoco supervisa contratos privados.'),
 T('La CNUDMI/UNCITRAL elaboró la CISG, pero no aprueba ni supervisa los contratos entre empresas.',true,'Es correcto: debe distinguirse la elaboración del marco normativo de la aprobación de operaciones privadas.'),
 T('PROMPERÚ es la entidad encargada de los tributos y del despacho aduanero de cada exportación.',false,'Se atribuye la función a otra institución. Corrección: esas tareas corresponden a SUNAT/Aduanas; PROMPERÚ brinda información y apoyo exportador.')
]),
C('modelo',5,'Destino y usuarios del Modelo ICC',2,[R('c5','páginas PDF 2 y 8 (impresas 79 y 85), §§5.1 y 5.5')],[
 M('¿Para qué operación está pensado específicamente el Modelo ICC estudiado?','Compraventa internacional de mercancía manufacturada para reventa.',['Venta directa al consumidor de cualquier servicio.','Adquisición de participaciones de una empresa.','Contratación laboral de los operarios del comprador.'],'La lectura delimita el modelo a bienes manufacturados para reventa y lo diseña para trabajar con la CISG.'),
 M('¿Qué empresas destaca la lectura como usuarias especialmente beneficiadas por el modelo?','Nuevas y pequeñas empresas con menor experiencia internacional.',['Únicamente grandes multinacionales con formularios propios.','Solo bancos que abren cartas de crédito.','Exclusivamente compañías de seguros de transporte.'],'El modelo ofrece una estructura útil a empresas sin formularios internacionales desarrollados; también puede servir a compradores y vendedores.'),
 T('El Modelo ICC de compraventa puede ser útil tanto para el vendedor como para el comprador.',true,'Es correcto: no queda reservado al exportador por llamarse contrato de venta; también puede emplearse en acuerdos de compra.'),
 T('El Modelo ICC estudiado está concebido para servir automáticamente a toda clase de operación internacional.',false,'El error es ignorar su ámbito. Corrección: está adaptado a compraventa de manufacturas para reventa; otras operaciones requieren disposiciones diferentes.')
]),
C('documentos',5,'Documentos que forman el contrato',3,[R('c5','páginas PDF 4–5 (impresas 81–82), §5.2'),R('p17','diapositiva 8')],[
 M('En la vía en que la orden de compra es la oferta, ¿qué función cumple la confirmación conforme del vendedor?','Aceptación de la oferta del comprador.',['Una nueva solicitud de cotización aunque no cambie ninguna condición.','Una contraoferta por el solo hecho de proceder del vendedor.','Un documento sin posible efecto en la formación del contrato.'],'La lectura presenta esta vía de formación: orden como oferta y confirmación del vendedor como aceptación.'),
 M('La proforma contiene una oferta vinculante y el comprador responde con una orden de compra que refleja sus condiciones. ¿Qué función cumple esa respuesta?','Aceptación de la oferta de la proforma.',['Contraoferta necesariamente, por usar otro documento.','La primera oferta en todos los casos, aunque la proforma ya fuera vinculante.','Una mera consulta que nunca puede expresar aceptación.'],'La función depende del contenido y de la secuencia, no solo del nombre: la proforma también puede ser la primera oferta.'),
 T('Una orden de compra puede funcionar como oferta o como aceptación, dependiendo de la negociación y su contenido.',true,'Es correcto: las dos vías de la lectura muestran funciones distintas para documentos con el mismo nombre.'),
 T('La factura proforma solo puede ser informativa y nunca puede constituir la oferta vinculante.',false,'El error es negar la segunda vía de formación. Corrección: una proforma puede ser la oferta que el comprador acepta.')
]),
C('proforma',5,'Proforma y solicitud de cotización',2,[R('c5','páginas PDF 4–5 (impresas 81–82), §5.2')],[
 M('¿Cuál es la función de una solicitud de cotización o RFQ?','Pedir precio y condiciones al posible vendedor.',['Confirmar necesariamente un pedido ya aceptado.','Emitir la factura comercial definitiva de una entrega realizada.','Declarar la conformidad de mercancía ya recibida.'],'La RFQ solicita información u oferta comercial; no es un mecanismo de controversias ni determina por sí sola la propiedad.'),
 M('¿Qué utilidad de la proforma destaca la lectura?','Permite anticipar cómo será la factura comercial y facilita gestionar un crédito documentario.',['Sustituye universalmente cualquier documento de transporte.','Garantiza que todos los bienes cumplen la calidad pactada.','Impide que el comprador formule una contraoferta.'],'La similitud con la factura final informa del costo previsto y sirve de base a los bancos; no certifica por sí sola la mercancía.'),
 T('La factura proforma puede ayudar al comprador a conocer el costo previsto de la operación.',true,'Es correcto: presenta anticipadamente las condiciones y la forma de la factura comercial definitiva.'),
 T('La RFQ y la confirmación del vendedor tienen necesariamente la misma función contractual.',false,'Se confunde pedir una cotización con confirmar un pedido. Corrección: la RFQ solicita precio y condiciones; una confirmación conforme puede expresar aceptación.')
]),
C('condiciones',5,'Condiciones específicas y generales',3,[R('c5','páginas PDF 7–8 (impresas 84–85), §§5.4 y 5.6')],[
 M('¿Dónde se recogen los datos de cantidad, mercancía, precio y lugar de entrega de una operación concreta en el Modelo ICC?','En las condiciones específicas.',['En las condiciones generales, como datos fijos de todas las ventas.','En los usos del sector, sin necesidad de identificar la venta concreta.','Únicamente en documentos posteriores a la ejecución del contrato.'],'Las específicas reúnen las decisiones de esa venta. Las generales las complementan con disposiciones jurídicas y soluciones por defecto.'),
 M('Una casilla de las condiciones específicas queda vacía. ¿Qué conclusión es correcta?','Puede operar la disposición por defecto de las condiciones generales.',['El tema queda necesariamente sin ninguna regulación.','El contrato entero se vuelve automáticamente inexistente.','La casilla vacía constituye una cláusula de arbitraje ad hoc.'],'La estructura del modelo incluye reglas por defecto; no toda omisión implica falta total de regulación.'),
 T('Las condiciones generales complementan las decisiones de las condiciones específicas y pueden proporcionar soluciones por defecto.',true,'Es correcto: esa es la función jurídica de la segunda parte del modelo.'),
 T('Las condiciones generales solo reproducen la cantidad y el precio concretos y no contienen soluciones jurídicas.',false,'La afirmación confunde las dos partes. Corrección: los datos concretos se incluyen en las específicas y las generales contienen disposiciones jurídicas complementarias.')
]),
C('otroscontratos',5,'Adaptación del modelo a la operación',2,[R('c5','páginas PDF 6–7 (impresas 83–84), §5.3'),R('p17','diapositiva 13')],[
 M('¿Qué necesidad distingue especialmente un suministro de varios años de una venta puntual?','Mecanismos para ajustar precios y organizar entregas periódicas.',['Conservar sin revisión las condiciones de una venta puntual, aunque cambien los costos.','Omitir el calendario porque habrá entregas periódicas.','Sustituir los mecanismos de ajuste por una descripción genérica del producto.'],'Un contrato prolongado debe contemplar fluctuaciones y entregas a lo largo del tiempo; una venta puntual puede no preverlas.'),
 M('Un acuerdo transmite derechos de uso de una patente, sin venta de bienes tangibles. ¿Qué categoría corresponde?','Licencia de propiedad intelectual o transferencia de tecnología.',['Compraventa puntual de mercancía manufacturada.','Inspección previa a la expedición.','Reserva simple de dominio.'],'La lectura distingue derechos de propiedad intelectual de bienes tangibles; requieren otro tipo de acuerdo.'),
 T('Un contrato de fabricación a medida puede necesitar coordinación específica antes y durante la producción.',true,'Es correcto: esa colaboración dificulta aplicar sin adaptación un modelo destinado a una compraventa puntual.'),
 T('Un contrato de compraventa de una máquina sirve automáticamente para una adquisición de acciones de la empresa fabricante.',false,'Se confunden bienes con participaciones. Corrección: una adquisición de acciones corresponde a otra operación, sujeta a reglas y cláusulas propias.')
]),
C('descripcion',5,'Descripción precisa y prueba documental',3,[R('c5','páginas PDF 8–10 (impresas 85–87), §5.6.b'),R('p17','diapositivas 14 y 18')],[
 M('¿Qué descripción reduce mejor la ambigüedad de calidad?','Una que establece características comprobables y criterios objetivos.',['La expresión «calidad excelente» sin otro criterio.','Una descripción que omite el uso comercial relevante.','La frase «producto premium» sin definirla.'],'La lectura recomienda precisión suficiente. Los calificativos vagos dificultan probar qué calidad se pactó.'),
 M('Se pacta una carta de crédito. La factura describe un producto superior, pero de manera distinta a la descripción exigida. ¿Qué advierte la lectura?','La discrepancia documental puede ocasionar el rechazo de los documentos.',['La mayor calidad obliga al banco a aceptar cualquier texto.','La calidad superior elimina las obligaciones documentarias.','La diferencia cambia el contrato a mediación.'],'La conformidad documental es independiente de que el bien sea mejor. Una diferencia de descripción puede impedir el pago documentario.'),
 T('Una descripción demasiado extensa puede generar discrepancias si una parte se omite en los documentos del crédito.',true,'Es correcto: la precisión debe ser útil; añadir detalles innecesarios también puede dificultar el cumplimiento documental.'),
 T('Una descripción como «muebles de primera» evita toda controversia aunque no defina criterios de calidad.',false,'El error es atribuir precisión a una frase vaga. Corrección: conviene definir características objetivas y suficientes para identificar lo pactado.')
]),
C('incoterms',5,'Entrega, Incoterms y lugar preciso',3,[R('c5','página PDF 11 (impresa 88), §5.6.d'),R('c4','páginas PDF 1–2 (impresas 65–66), §4.1')],[
 M('¿Qué NO determinan las reglas Incoterms según las lecturas?','Los efectos de la compraventa sobre la titularidad de la mercancía.',['La distribución de determinados costos entre comprador y vendedor.','El punto de transmisión del riesgo de entrega.','Responsabilidades relativas al despacho aduanero.'],'Los Incoterms organizan obligaciones de entrega, costos y riesgo entre las partes; no regulan los efectos sobre la propiedad.'),
 M('¿Qué precisión conviene acompañar a la regla Incoterms que se incorpore al contrato?','La versión y el lugar o punto pertinente definido con precisión.',['Solo la nacionalidad de los árbitros.','Un calificativo general como «entrega habitual».','La afirmación de que todos los gastos y riesgos coinciden siempre.'],'La lectura destaca que el lugar exacto importa y que reglas sectoriales pueden diferir. Debe indicarse expresamente la versión deseada.'),
 T('Las obligaciones del porteador frente al expedidor se rigen por el contrato y las normas de transporte, no simplemente por el Incoterm pactado entre comprador y vendedor.',true,'Es correcto: los Incoterms cubren relaciones entre vendedor y comprador; no sustituyen las normas del transporte.'),
 T('Incluir una regla Incoterms vuelve innecesario precisar el punto de entrega.',false,'El error es suponer precisión automática. Corrección: deben describirse el lugar y, cuando corresponda, el punto exacto pertinente.')
]),
C('psi',5,'Inspección previa a la expedición',2,[R('c5','páginas PDF 11–12 (impresas 88–89), §5.6.f')],[
 M('Si se acuerda inspección previa a la expedición, ¿qué debe hacer el vendedor según el modelo descrito?','Notificar cuándo estará disponible la mercancía para inspección.',['Esperar a que los bienes lleguen al comprador para avisar.','Suponer que pactar la inspección elimina la necesidad de coordinar su disponibilidad.','Delegar el aviso al comprador aunque este no conozca cuándo están listos.'],'La disponibilidad debe comunicarse para que pueda realizarse el control convenido antes del envío.'),
 M('¿Qué inspector aconseja la lectura para reducir dudas de neutralidad?','Una agencia independiente y reputada.',['Un empleado del vendedor, por considerarlo neutral por el solo hecho de conocer los bienes.','Un agente del comprador, por considerar que su vínculo garantiza neutralidad.','Cualquiera de las partes, sin necesidad de definir independencia ni alcance.'],'La independencia del inspector favorece un control neutral. Un agente de una parte puede suscitar dudas cuando aparece la disputa.'),
 T('La inspección previa al envío puede ser un control de calidad y una herramienta contra el fraude.',true,'Es correcto: la lectura destaca ambas utilidades y recomienda definir sus detalles contractualmente.'),
 T('La inspección previa a la expedición se realiza necesariamente después de entregar la mercancía en destino.',false,'La afirmación invierte el momento. Corrección: es una inspección anterior al envío, cuyos lugar, alcance y responsables deben acordarse.')
]),
C('dominio',5,'Reserva de dominio',3,[R('c5','página PDF 12 (impresa 89), §5.6.g')],[
 M('¿Qué establece la cláusula simple de reserva de dominio?','El vendedor conserva la propiedad hasta el pago íntegro del precio.',['El vendedor conserva únicamente el riesgo aunque el comprador pague todo.','La propiedad pasa siempre al cargar el buque, por mandato de la CISG.','El comprador adquiere la propiedad solo por pedir una cotización.'],'La reserva simple vincula la titularidad al pago íntegro; su eficacia debe examinarse con el derecho nacional aplicable.'),
 M('¿Qué distingue a una reserva ampliada respecto de una simple?','Busca extender la protección a elementos adicionales, como el producto de la reventa o bienes transformados.',['Elimina la necesidad de verificar la ley nacional.','Convierte todo reclamo en una sentencia automáticamente ejecutable.','Se limita necesariamente al pago de ese único precio sin más alcance.'],'La lectura menciona ampliaciones sobre ingresos de reventa y bienes mezclados o manufacturados. Su admisibilidad depende de la legislación.'),
 T('La validez y alcance de una reserva de dominio deben comprobarse conforme al derecho nacional aplicable.',true,'Es correcto: ni la CISG ni los Incoterms regulan esos efectos de titularidad; algunas jurisdicciones pueden exigir formalidades.'),
 T('La reserva simple transmite la propiedad al comprador antes del pago íntegro por el solo hecho de entregar físicamente los bienes.',false,'El error es ignorar la reserva. Corrección: bajo una cláusula simple válida, el vendedor conserva la propiedad hasta el pago completo.')
]),
C('pago',5,'Medios y condiciones de pago',3,[R('c5','página PDF 13 (impresa 90), §5.6.h'),R('n','página PDF 14')],[
 M('El comprador paga antes de la entrega. ¿Qué modalidad corresponde?','Pago anticipado.',['Cuenta abierta.','Cobranza con documentos contra aceptación.','Pago después de la entrega contra factura.'],'En el anticipo se paga antes de entregar. La cuenta abierta permite cobrar después de la entrega en las condiciones acordadas.'),
 M('En una cobranza documentaria, ¿qué significan las opciones D/P y D/A de la lectura?','Documentos contra pago y documentos contra aceptación.',['Documentos contra aceptación y documentos contra pago, respectivamente.','Pago anticipado y cuenta abierta, respectivamente.','Crédito confirmado y crédito sin confirmar, respectivamente.'],'Son dos opciones de cobranza: la entrega documental se vincula al pago o a la aceptación según se pacte.'),
 T('La cobranza documentaria y el crédito documentario son modalidades diferentes; no basta que ambas involucren documentos para tratarlas como idénticas.',true,'Es correcto: los bancos tramitan una cobranza bajo instrucciones, mientras el crédito exige una presentación documentaria conforme a sus condiciones.'),
 T('En cuenta abierta, el comprador paga necesariamente antes de que se entregue la mercancía.',false,'Se confunde con el anticipo. Corrección: en cuenta abierta se cobra después de la entrega, conforme al plazo pactado.')
]),
C('documental',5,'Obligaciones documentarias',3,[R('c5','página PDF 13 (impresa 90), §5.6.i'),R('c4','página PDF 8 (impresa 72), §4.5.b')],[
 M('En una venta documentaria, ¿qué afirmación es correcta?','Entregar documentos conformes puede ser tan importante como entregar mercancía conforme.',['La entrega física vuelve irrelevante cualquier documento.','Los bancos comprueban directamente todos los bienes en vez de los documentos.','El documento de transporte puede reemplazarse sin atender a lo exigido.'],'La lectura advierte que un incumplimiento documental puede comprometer la operación completa, especialmente con carta de crédito.'),
 M('El crédito exige un documento de transporte específico y el vendedor presenta otro. ¿Qué problema existe?','Una posible falta de conformidad documental, aunque los bienes sean correctos.',['Cumplimiento completo, porque la conformidad física corrige el documento equivocado.','Una mera diferencia de calidad del bien, sin relevancia documental.','Un defecto que el banco debe ignorar por existir entrega física.'],'Bienes conformes y documentos conformes son obligaciones diferentes. Presentar el tipo correcto de documento es esencial para la gestión documentaria.'),
 T('La lectura recomienda coordinar el contrato de venta, la carta de crédito, el seguro y el documento de transporte.',true,'Es correcto: deben concordar. La «sinfonía» de la operación falla cuando los instrumentos se contradicen.'),
 T('Como el comprador recibe bienes conformes, el banco debe ignorar cualquier discrepancia en los documentos del crédito.',false,'El error es equiparar bienes y documentos. Corrección: los bancos tratan con documentos; una discrepancia documental puede impedir su aceptación.')
]),
C('fecha',5,'Fecha de entrega y fecha de rescisión',3,[R('c5','páginas PDF 11 y 14 (impresas 88 y 91), §5.6.e y j')],[
 M('¿Qué función tiene la fecha de rescisión opcional descrita en el Modelo ICC?','Permite al comprador rescindir inmediatamente si no hay entrega en la fecha límite pactada.',['Termina toda venta automáticamente por mutuo acuerdo en esa fecha.','Determina la fecha de firma de la carta de crédito.','Sustituye la descripción de calidad de la mercancía.'],'Es una facultad ante la falta de entrega en una fecha límite, no una extinción automática general. Las notas de la página 14 simplifican incorrectamente este punto.'),
 M('¿Cuál es la diferencia entre fecha de entrega y fecha de rescisión en el modelo descrito?','La primera fija cuándo se debe entregar; la segunda puede establecer el límite que habilita a rescindir por falta de entrega.',['Ambas indican necesariamente el día en que se paga al inspector.','La fecha de entrega decide qué tribunal es competente.','La fecha de rescisión solo identifica la moneda del precio.'],'Son cláusulas relacionadas, pero con funciones diferentes: cumplimiento de la entrega y remedio ante su falta al límite pactado.'),
 T('Las condiciones de entrega temporal pueden expresarse mediante una fecha concreta o un período.',true,'Es correcto: la lectura ofrece ambas opciones; deben distinguirse de la cláusula opcional de fecha límite para rescindir.'),
 T('La fecha de rescisión del modelo hace que cualquier compraventa termine automáticamente, incluso si el vendedor entrega conforme y a tiempo.',false,'El error es hacer automática e incondicionada la terminación. Corrección: la cláusula permite al comprador rescindir si no se entrega en la fecha límite estipulada.')
]),
C('limites',5,'Límites de responsabilidad',2,[R('c5','página PDF 14 (impresa 91), §5.6.k–m')],[
 M('¿Qué busca una cláusula de límite de responsabilidad por falta de conformidad?','Delimitar la indemnización por los perjuicios de una entrega no conforme.',['Fijar el momento hasta el que el comprador puede iniciar acciones.','Otorgar un plazo adicional para entregar, sin regular indemnización.','Definir cuándo el comprador paga el precio, sin tratar los perjuicios.'],'La cláusula organiza el alcance económico de responsabilidad; no decide foro, titularidad ni método de inspección.'),
 M('¿Qué opción contemplan las condiciones generales descritas cuando el comprador conserva bienes no conformes?','Una reducción o descuento en el precio dentro del marco aplicable.',['La exclusión automática de todo remedio por conservar los bienes.','El deber de resolver el contrato como único remedio posible.','La reparación automática de los bienes por el banco del crédito.'],'Conservar los bienes y obtener una reducción son compatibles en la opción descrita; no significa aceptar sin ninguna compensación.'),
 T('Las partes pueden ajustar mediante cláusulas específicas ciertas disposiciones por defecto sobre retrasos o falta de conformidad.',true,'Es correcto: el modelo prevé opciones para variar esas soluciones, sujetas al marco jurídico aplicable.'),
 T('Una indemnización por retraso de cualquier magnitud es necesariamente exigible en todas las jurisdicciones.',false,'El error es omitir límites legales. Corrección: la lectura advierte que un nivel muy alto puede considerarse punitivo y no exigible en algunas jurisdicciones.')
]),
C('prescripcion',5,'Prescripción y reglas por defecto',1,[R('c5','página PDF 14 (impresa 91), §5.6.n')],[
 M('¿Qué materia regula la cláusula de prescripción del modelo descrito?','El plazo para emprender determinadas acciones jurídicas.',['El día máximo de entrega cuyo incumplimiento permite rescindir.','El plazo de pago del precio después de la factura.','El lapso para disponer de bienes antes de una inspección.'],'Prescripción se refiere al tiempo para ejercer acciones; no se confunde con entrega, inspección ni especificaciones del bien.'),
 M('¿Qué permite la cláusula opcional de prescripción en el texto estudiado?','Estipular un plazo distinto del previsto por defecto.',['Fijar el precio sin regular el ejercicio de acciones.','Elegir tribunal en lugar de establecer un plazo de acciones.','Cambiar automáticamente la fecha de entrega de los bienes.'],'La lectura contempla ampliar o reducir el plazo por defecto mediante la cláusula correspondiente, dentro del marco aplicable.'),
 T('El plazo de prescripción para emprender acciones y la fecha de entrega cumplen funciones distintas.',true,'Es correcto: uno regula el ejercicio de acciones; la otra, el momento de cumplir la entrega.'),
 T('La cláusula de prescripción identifica qué agencia independiente inspeccionará los bienes.',false,'Se confunde prescripción con inspección. Corrección: la prescripción se refiere al plazo para ejercer acciones jurídicas.')
]),
C('precio',5,'Identificación de las partes',2,[R('c5','páginas PDF 6, 8 y 10 (impresas 83, 85 y 87), §§5.2.e y 5.6.a–c')],[
 M('¿Qué precaución recomienda la lectura al identificar a la contraparte?','Comprobar que sea exactamente la empresa cuyas referencias crediticias se revisaron.',['Usar cualquier nombre comercial parecido.','Prescindir del nombre si firma una persona física.','Confundir al representante con la empresa sin aclarar quién se obliga.'],'La denominación correcta y la representación deben permitir identificar quién queda obligado y a quién se evaluó.'),
 M('Una persona firma en representación de una empresa. ¿Qué debe quedar claro?','Si quien queda obligado por el contrato es la empresa o su representante.',['Solo el cargo informal con el que se presenta, aunque no se identifique a la empresa.','Únicamente el nombre de otra empresa con referencias bancarias similares.','Que la firma vuelve irrelevante identificar a la contraparte.'],'La identificación debe precisar a quién se atribuyen las obligaciones y quién actúa en representación de la empresa.'),
 T('Debe identificarse con precisión a la empresa contratante y aclarar quién se obliga cuando firma un representante.',true,'Es correcto: identificar al firmante no basta si queda incierto si se obliga él o la empresa.'),
 T('La empresa que aparece en el contrato puede ser distinta de la investigada crediticiamente, siempre que sus nombres se parezcan.',false,'El error es aceptar una identidad aproximada. Corrección: la contraparte debe ser exactamente la empresa evaluada, con su denominación correcta.')
]),
C('riesgopropiedad',5,'Riesgo y propiedad',3,[R('p18','diapositivas 4 y 6–7'),R('c4','página PDF 8 (impresa 72), §4.5.b'),R('c5','página PDF 12 (impresa 89), §5.6.g')],[
 M('¿Qué diferencia hay entre riesgo y propiedad?','El riesgo se refiere a quién soporta una pérdida fortuita; la propiedad, a la titularidad jurídica.',['Son dos nombres para el pago anticipado.','La propiedad siempre se transfiere al mismo tiempo que el riesgo.','El riesgo identifica exclusivamente qué ley rige el arbitraje.'],'Son planos diferentes y no necesariamente cambian a la vez. Sus efectos deben examinarse en las reglas y pactos pertinentes.'),
 M('Las partes quieren fijar cuándo cambia la titularidad jurídica de los bienes. ¿Qué deben examinar?','El derecho nacional aplicable y lo válidamente pactado.',['Solo el punto de riesgo del Incoterm, que decide necesariamente también la propiedad.','Únicamente quién contrata el transporte.','La fecha del seguro como sustituto de las normas de propiedad.'],'El régimen de los efectos sobre la propiedad no se determina por el costo del transporte ni por la póliza; la lectura remite al derecho nacional.'),
 T('La propiedad puede quedar sujeta a una reserva de dominio y no coincidir en el tiempo con la transmisión del riesgo.',true,'Es correcto: la titularidad y la asignación de pérdidas fortuitas son cuestiones distintas.'),
 T('Pagar el transporte equivale necesariamente a soportar todo el riesgo de pérdida durante el trayecto.',false,'El error es equiparar costo y riesgo. Corrección: deben examinarse por separado las obligaciones, el punto de transmisión del riesgo y lo pactado.')
]),
C('estrategia',6,'Prevención y estrategia de controversias',2,[R('c6','páginas PDF 2–3 (impresas 93–94), §6.1')],[
 M('¿Qué medida ayuda a prevenir controversias desde la contratación?','Verificar solvencia, redactar obligaciones claras y acordar un mecanismo de solución.',['Dejar todas las responsabilidades sin definir.','Elegir el mecanismo solo después de adoptar posiciones hostiles.','Suponer que ganar un juicio garantiza el cobro.'],'La prevención combina conocer a la contraparte, claridad y planificación. Acordar el procedimiento suele ser más fácil mientras existe cooperación.'),
 M('¿Qué costo comercial destaca el capítulo además de abogados, traducciones y viajes?','Perder una relación comercial y el acceso a un mercado desarrollado durante años.',['Que toda relación comercial deba terminar al aparecer cualquier desacuerdo.','Que la existencia de socios comerciales vuelva irrelevante el costo del conflicto.','Que el único costo relevante sea el honorario de los abogados.'],'La controversia puede destruir una relación valiosa. Por ello se consideran continuidad y efectos comerciales, no solo costos judiciales.'),
 T('Las partes pueden acordar arbitraje o mecanismos alternativos después de surgir la disputa, aunque lograrlo puede ser más difícil.',true,'Es correcto: pactarlo antes es recomendable, pero la lectura no lo presenta como el único momento posible.'),
 T('No hace falta planificar cómo cobrar porque una decisión favorable elimina por sí sola todos los obstáculos de ejecución.',false,'El error es confundir ganar con cobrar. Corrección: deben evaluarse activos, lugar de ejecución y costos de hacer cumplir la decisión.')
]),
C('adaptacion',6,'Cláusulas de adaptación',3,[R('c6','páginas PDF 3–4 (impresas 94–95), §6.2.1'),R('p18','diapositiva 14')],[
 M('Un suministro ajusta el precio cada semestre según un índice público. ¿Qué cláusula aplica?','Reajuste de precios.',['Cláusula de variación o sustitución de productos.','Cláusula de mejor precio respecto de otros clientes.','Cláusula de demoras justificables.'],'El índice permite adaptar el precio con una regla predefinida, especialmente útil en relaciones prolongadas.'),
 M('¿Qué permite una cláusula de variación o sustitución como la descrita?','Cambiar determinados bienes conservando la funcionalidad acordada.',['Sustituir unilateralmente toda obligación por cualquier producto.','Elegir automáticamente el tribunal del vendedor.','Transmitir acciones de la empresa en lugar del precio.'],'La variación se regula dentro de condiciones pactadas y preservando la funcionalidad; no es una autorización ilimitada.'),
 T('Las cláusulas de mejor precio o trato preferente deben examinarse también a la luz de las normas de competencia aplicables.',true,'Es correcto: la lectura advierte que su validez requiere atención a esas normas, no solo al beneficio comercial pretendido.'),
 T('Las cláusulas de adaptación tienen por única función declarar que todo cambio de costos es fuerza mayor.',false,'El error es identificar adaptación con exoneración. Corrección: pueden prever revisión de precios, sustituciones o renegociación; la fuerza mayor atiende a impedimentos y requisitos propios.')
]),
C('renuncia',6,'Tolerancia y renuncia a derechos',2,[R('c6','página PDF 4 (impresa 95), §6.2.2.a'),R('c4','página PDF 8 (impresa 72), §4.6')],[
 M('Una empresa tolera un retraso puntual, pero quiere conservar su derecho a exigir puntualidad en el futuro. ¿Qué medida recomienda la lectura?','Dejar constancia escrita de su disconformidad y del carácter puntual de la tolerancia.',['Guardar silencio reiterado para reforzar automáticamente sus derechos.','Destruir el calendario de entregas.','Cambiar de foro sin acuerdo ni regla aplicable.'],'La tolerancia reiterada puede interpretarse como renuncia. La constancia escrita ayuda a evitar que se entienda así.'),
 M('¿Qué riesgo puede surgir de perdonar repetidamente el mismo incumplimiento menor?','Que se interprete como abandono del derecho a objetarlo.',['Que el perdón refuerce automáticamente el derecho a exigir sin aclaración alguna.','Que se resuelva necesariamente todo el contrato por ese solo perdón.','Que la tolerancia valga siempre como una modificación escrita y firmada.'],'El riesgo es de renuncia o aceptación de una práctica, no una transformación del tipo de contrato.'),
 T('Una cláusula que exige formalizar por escrito las modificaciones puede ayudar a evitar renuncias no deseadas, según el marco aplicable.',true,'Es correcto: la lectura la propone como protección, sin afirmar su eficacia universal en toda jurisdicción.'),
 T('Aceptar una demora aislada obliga necesariamente a aceptar todas las demoras futuras.',false,'El error es atribuir un efecto inevitable. Corrección: puede tolerarse un incumplimiento puntual, cuidando que no se interprete como renuncia general.')
]),
C('renegociacion',6,'Renegociación y solución acordada',2,[R('c6','página PDF 4 (impresa 95), §6.2.2.b'),R('p18','diapositivas 14 y 16')],[
 M('Los directivos acuerdan revisar el calendario para salvar la relación. ¿Qué mecanismo describe mejor la situación?','Renegociación del contrato.',['Renuncia permanente al derecho a reclamar.','Ayuda pericial que impone la decisión final.','Arbitraje que dicta un laudo sobre el calendario.'],'Las propias partes modifican el acuerdo por consentimiento. No hay una decisión impuesta por tribunal o árbitro.'),
 M('¿Qué puede prever una cláusula de renegociación?','Que los directivos deban reunirse antes de acudir a vías más confrontacionales.',['Que un mediador dicte necesariamente sentencia.','Que se elimine toda necesidad de mutuo acuerdo.','Que el perito transmita la propiedad de la mercancía.'],'La lectura contempla reuniones de la dirección como opción u obligación para intentar resolver el desacuerdo.'),
 T('Las partes pueden modificar el contrato de mutuo acuerdo para resolver un problema surgido durante su ejecución.',true,'Es correcto: la nueva negociación busca una solución acordada y puede estar prevista contractualmente.'),
 T('La renegociación permite a una parte imponer por sí sola un nuevo precio al resto.',false,'Se elimina indebidamente el acuerdo. Corrección: renegociar supone buscar y convenir cambios entre las partes, no imponerlos unilateralmente.')
]),
C('perito',6,'Peritaje y prueba especializada',2,[R('c6','páginas PDF 4–5 (impresas 95–96), §6.2.2.c')],[
 M('Un especialista independiente examina por qué falló una máquina y emite un informe para facilitar el acuerdo. ¿Qué intervención es?','Ayuda pericial.',['Arbitraje que necesariamente produce un laudo.','Exequátur de una sentencia extranjera.','Elección de derecho sustantivo.'],'El perito aporta conocimientos técnicos o especializados. Su informe no equivale por sí solo a una decisión vinculante.'),
 M('¿Qué afirmación sobre un dictamen pericial es correcta?','Puede persuadir a un juez o árbitro sin convertirse por sí mismo en sentencia o laudo.',['Siempre resuelve definitivamente la disputa sin otro acto.','Solo puede pedirse después de obtener sentencia.','No puede abordar aspectos financieros ni técnicos.'],'La lectura destaca su valor como análisis y prueba. Incluso puede pedirse sin controversia o por un tribunal arbitral.'),
 T('Un experto puede analizar calidad, causas de una falla o consecuencias de un retraso.',true,'Es correcto: son ejemplos expresamente incluidos en la ayuda pericial de la lectura.'),
 T('El informe de un perito constituye, por sí solo, una decisión vinculante y ejecutable equivalente a un laudo.',false,'Se confunde asesoramiento con decisión. Corrección: el perito aporta conclusiones especializadas; no son por sí solas un laudo o sentencia.')
]),
C('leyforo',6,'Ley aplicable, foro y mecanismo',3,[R('c4','página PDF 5 (impresa 69), §4.4'),R('p18','diapositivas 15–17')],[
 M('¿Qué cuestión responde la elección de la ley aplicable?','Qué normas gobiernan el fondo del contrato.',['Qué árbitro revisará físicamente los bienes.','En qué almacén se empaquetará la mercancía.','Qué banco debe abrir cualquier crédito.'],'La ley de fondo se distingue de la jurisdicción, del mecanismo de solución y de los detalles de ejecución comercial.'),
 M('Se elige una legislación para el contrato. ¿Qué falta distinguir?','Qué tribunal es competente y qué mecanismo resolverá la controversia.',['La imposibilidad absoluta de usar arbitraje.','La obligación automática de litigar ante tribunales de ese país.','La sustitución de todas las reglas procesales por la ley elegida.'],'Elegir ley no fija por sí solo tribunal ni arbitraje. La sede y las reglas procedimentales también deben distinguirse del fondo.'),
 T('La ley aplicable al fondo y las reglas del procedimiento arbitral son cuestiones distintas.',true,'Es correcto: el material distingue derecho sustantivo y procesal; no deben deducirse como una sola elección.'),
 T('Elegir la ley del país del vendedor determina automáticamente que sus tribunales sean los únicos competentes.',false,'El error es confundir ley y foro. Corrección: deben examinarse separadamente la ley que rige y el tribunal o mecanismo competente.')
]),
C('jurisdiccion',6,'Jurisdicción y forum shopping',2,[R('c6','páginas PDF 6–7 (impresas 97–98), §6.3.2')],[
 M('¿Qué significa forum shopping en la lectura?','Buscar el foro que una parte considera más favorable o conveniente.',['Elegir qué mercancía se compra en una feria.','Pedir a un banco una cotización de moneda.','Seleccionar el tipo de embalaje.'],'El concepto se refiere a dónde litigar y a las ventajas que una parte espera encontrar, no a compras comerciales.'),
 M('¿Qué debe tener el tribunal ante el que se presenta la demanda?','Competencia para conocer el caso.',['La nacionalidad del demandante en todos los supuestos.','La facultad de ignorar cualquier norma procesal.','La propiedad de los bienes objeto de la venta.'],'Jurisdicción trata de la autoridad para conocer la controversia. La preferencia de una parte no crea por sí sola competencia.'),
 T('Una cláusula de elección de foro puede reducir incertidumbres, pero su reconocimiento depende de las reglas aplicables.',true,'Es correcto: la lectura advierte que no necesariamente será respetada en todos los países y circunstancias.'),
 T('Cualquier tribunal elegido por una parte queda obligado a admitir la demanda aunque carezca de competencia.',false,'El error es atribuir jurisdicción por mera preferencia. Corrección: se necesita un tribunal competente conforme al marco aplicable.')
]),
C('conflictoleyes',6,'Conflicto de leyes',1,[R('c6','página PDF 7 (impresa 98), §6.3.3')],[
 M('Si no hay una elección válida de ley aplicable, ¿a qué puede acudir el tribunal?','A las reglas de conflicto de leyes para determinarla.',['A la libre preferencia unilateral del transportista.','Al color del embalaje como criterio suficiente.','A la sustitución automática de la ley por una proforma.'],'Las reglas de conflicto permiten identificar el ordenamiento pertinente considerando conexiones de la operación.'),
 M('¿Qué conexiones menciona la lectura al explicar la determinación de la ley aplicable?','Lugar de negociación o firma, lugar de cumplimiento y domicilios de las partes.',['Únicamente el idioma del catálogo.','Solo el valor de la prima del seguro.','La nacionalidad de cualquier testigo, como regla exclusiva.'],'Son vínculos relevantes para el análisis de conflicto de leyes; la lectura no lo reduce a una regla única y universal.'),
 T('La falta de elección válida de ley no significa que el contrato quede libre de todo ordenamiento jurídico.',true,'Es correcto: el tribunal puede identificar el derecho aplicable mediante las normas de conflicto.'),
 T('Las reglas de conflicto de leyes eligen qué producto debe fabricarse, sin relación con el derecho aplicable.',false,'Se atribuye una función comercial al mecanismo jurídico. Corrección: estas reglas ayudan a determinar qué ordenamiento rige el asunto.')
]),
C('ejecucion',6,'Ejecución y exequátur',2,[R('c6','páginas PDF 7–8 (impresas 98–99), §6.3.4')],[
 M('Se obtiene sentencia en un país, pero el deudor tiene activos en otro. ¿Qué procedimiento puede resultar necesario?','Reconocimiento de la sentencia extranjera mediante exequátur.',['Una nueva elección de ley que por sí sola haga ejecutable la sentencia.','Una apelación ordinaria que sustituya necesariamente el reconocimiento.','Una renegociación obligatoria del contrato original como único modo de cobrar.'],'El exequátur permite reconocer la decisión extranjera conforme al marco del país donde se pretende hacerla efectiva.'),
 M('¿Qué conviene comprobar antes de demandar para obtener una indemnización?','Si el deudor tiene activos suficientes y dónde se puede ejecutar la decisión.',['Solo que el importe reclamado sea alto.','Que la sentencia se cobrará automáticamente en cualquier país.','Que cualquier insolvencia mejora necesariamente el cobro.'],'Ganar no garantiza recuperar dinero. La existencia y ubicación de activos y la posibilidad de ejecución son decisivas.'),
 T('El reconocimiento y la ejecución de una sentencia extranjera pueden variar de un país a otro.',true,'Es correcto: la lectura destaca que no existe una respuesta única y que importan normas y convenios aplicables.'),
 T('Obtener una sentencia favorable equivale necesariamente a cobrar de inmediato, incluso si el deudor carece de activos.',false,'El error es confundir decisión con cobro. Corrección: debe lograrse su ejecución y existir bienes o recursos sobre los que hacerla efectiva.')
]),
C('vias',6,'Negociación, mediación, arbitraje y litigio',3,[R('p18','diapositivas 15–16'),R('n','página PDF 18')],[
 M('Un tercero facilita que las partes alcancen un acuerdo sin imponerles una sentencia. ¿Qué vía corresponde?','Mediación.',['Arbitraje.','Litigio judicial.','Exequátur.'],'En la mediación la solución es acordada por las partes con ayuda del tercero; en el arbitraje el árbitro decide mediante laudo.'),
 M('¿Cuál es la asociación correcta entre vía y resultado?','Arbitraje: decisión vinculante de árbitros mediante laudo.',['Mediación: sentencia obligatoria dictada por el mediador.','Negociación: decisión impuesta por un tribunal estatal.','Litigio: informe técnico sin decisión judicial.'],'Cada mecanismo tiene un papel distinto: acuerdo directo, facilitación de acuerdo, laudo o sentencia.'),
 T('En la negociación, las propias partes buscan una solución directa y flexible.',true,'Es correcto: no necesitan una decisión impuesta por un tercero para alcanzar el acuerdo.'),
 T('La mediación y el arbitraje producen necesariamente la misma clase de decisión impuesta por el tercero.',false,'Se confunden mecanismos. Corrección: el mediador facilita un acuerdo; el árbitro dicta una decisión vinculante conforme al convenio y reglas aplicables.')
]),
C('ventajasarbitraje',6,'Ventajas y alcance del arbitraje',3,[R('c6','páginas PDF 8–9 (impresas 99–100), §6.4.1')],[
 M('Una disputa exige conocer un proceso industrial. ¿Qué ventaja del arbitraje es especialmente pertinente?','Posibilidad de designar árbitros con experiencia técnica o sectorial.',['Garantía de que no habrá ningún gasto.','Obligación de usar un idioma desconocido.','Imposibilidad de adaptar el procedimiento.'],'La especialización puede ayudar a entender la materia y reducir el tiempo necesario para explicarla al decisor.'),
 M('¿Qué instrumento menciona la lectura para facilitar el reconocimiento y ejecución de laudos extranjeros?','La Convención de Nueva York de 1958.',['La Convención de Viena sobre compraventa, como régimen específico de ejecución de laudos.','La elección del Incoterm, como procedimiento de reconocimiento de laudos.','La cláusula de reserva de dominio, como convenio internacional arbitral.'],'La Convención citada se refiere al reconocimiento y ejecución de sentencias arbitrales extranjeras, bajo sus condiciones.'),
 T('La elección de idioma y la flexibilidad procedimental son ventajas potenciales del arbitraje descritas en el capítulo.',true,'Es correcto: pueden facilitar el procedimiento y reducir dificultades de traducción o de organización.'),
 T('La neutralidad del arbitraje exige que su sede esté siempre en un país distinto de los países de ambas partes.',false,'El error es convertir una opción en obligación. Corrección: puede elegirse un país neutral, pero también puede celebrarse en el país de una de las partes.')
]),
C('limitesarbitraje',6,'Costos y revisión del laudo',3,[R('c6','página PDF 9 (impresa 100), §6.4.2'),R('p18','diapositiva 16')],[
 M('¿Cuál es la afirmación INCORRECTA sobre el arbitraje?','Está garantizado que todo arbitraje será barato y rápido.',['Puede implicar honorarios de árbitros y otros gastos.','Hay procedimientos complejos que duran años.','La revisión del laudo suele ser más limitada que una apelación judicial ordinaria.'],'La lectura distingue una ventaja relativa de una garantía universal. Costo y duración dependen del procedimiento concreto.'),
 M('¿Por qué el carácter final del laudo puede verse como ventaja y desventaja?','Puede cerrar antes la controversia, pero limita las posibilidades de revisar una decisión desfavorable.',['Porque hace imposible ejecutar cualquier decisión.','Porque permite apelar indefinidamente como regla general.','Porque elimina todos los honorarios profesionales.'],'La revisión limitada reduce prolongación, pero también oportunidades de corrección. No significa ausencia absoluta de controles.'),
 T('La flexibilidad arbitral permite organizar garantías procesales, como actas escritas, si las partes las consideran convenientes.',true,'Es correcto: el capítulo no equipara flexibilidad con ausencia necesaria de rigor; el procedimiento puede estructurarse.'),
 T('Como el arbitraje es privado, su costo y duración carecen de importancia al escoger el mecanismo.',false,'El error es ignorar factores de decisión. Corrección: también deben compararse costos, tiempo, ejecución y continuidad de la relación comercial.')
]),
C('adhoc',6,'Arbitraje institucional y ad hoc',3,[R('p18','diapositiva 17')],[
 M('Una organización administra el arbitraje conforme a sus reglas. ¿Qué tipo corresponde?','Arbitraje institucional.',['Arbitraje ad hoc no administrado.','Mediación sin decisión vinculante.','Litigación estatal.'],'El elemento distintivo es la administración institucional, no la mera existencia de reglas escritas.'),
 M('¿Cuál describe correctamente al arbitraje ad hoc?','No es administrado por una institución, aunque puede adoptar reglas preexistentes.',['Carece necesariamente de cualquier regla.','Es un juicio ante tribunales estatales.','Solo sirve para inspeccionar mercancía antes del envío.'],'Ad hoc se refiere a ausencia de administración institucional; no implica falta de procedimiento o de reglas.'),
 T('La cláusula arbitral debe atender a sede, idioma y designación de árbitros, entre otros aspectos.',true,'Es correcto: conviene precisar el procedimiento y distinguirlo de la ley aplicable al fondo.'),
 T('Si un arbitraje adopta reglas preexistentes, necesariamente deja de ser ad hoc y pasa a ser administrado por una institución.',false,'Se confunden reglas con administración. Corrección: un arbitraje ad hoc puede utilizar reglas preexistentes sin administración institucional.')
]),
C('fuerzamayor',6,'Fuerza mayor y exoneración',3,[R('p18','diapositivas 13–14'),R('c5','página PDF 15 (impresa 92), §5.6.q')],[
 M('¿Qué debe examinarse ante una alegación de exoneración por impedimento?','Control de la parte, previsibilidad, posibilidad de evitar o superar el impedimento y notificación.',['Solo que la parte prefiera no cumplir.','Únicamente que el precio de reventa haya bajado.','Que el contrato tenga muchas páginas.'],'La clase exige evaluar el impedimento y sus efectos; no basta nombrar un evento o invocar inconveniencia comercial.'),
 M('¿Cuál es la precisión correcta sobre el artículo 79 presentada en clase?','La exoneración se refiere principalmente a daños y no extingue automáticamente todas las demás consecuencias contractuales.',['Borra siempre toda obligación y cualquier remedio.','Transfiere de inmediato la propiedad al comprador.','Elimina la necesidad de comunicar el impedimento.'],'La exoneración tiene alcance y requisitos; no equivale a resolver automáticamente todo el vínculo ni elimina todos los remedios.'),
 T('Prever una revisión del precio adapta el contrato; alegar fuerza mayor exige examinar un impedimento y sus requisitos.',true,'Es correcto: adaptación y exoneración cumplen funciones diferentes, aunque ambas puedan gestionarse mediante cláusulas.'),
 T('Basta mencionar una catástrofe para obtener exoneración sin examinar su relación con el incumplimiento ni notificar sus efectos.',false,'El error es tratar el evento como exoneración automática. Corrección: deben evaluarse el impedimento, sus requisitos y la notificación a la otra parte.')
])
];
const BANCO = CONCEPTOS.flatMap(c=>c.items.map((q,i)=>({...q,id:`${c.id}-${i+1}`,concept:c.id,chapter:c.chapter,topic:c.title,weight:c.weight,refs:c.refs})));
if(typeof module!=='undefined') module.exports={BANCO,CONCEPTOS,FUENTES};
